mapper.sql:
FROM USERS u LEFT JOIN ( SELECT user_idx, COUNT(*) AS social_count, GROUP_CONCAT(provider ORDER BY provider) AS linked_providers FROM USER_SOCIAL GROUP BY user_idx ) s ON u.user_idx = s.user_idx LEFT JOIN ( SELECT user_idx, MAX(login_at) AS last_login_at, SUBSTRING_INDEX(GROUP_CONCAT(login_method ORDER BY login_at DESC), ',', 1) AS last_login_method, SUM(CASE WHEN is_success = 1 THEN 1 ELSE 0 END) AS login_success_count, SUM(CASE WHEN is_success = 0 THEN 1 ELSE 0 END) AS login_fail_count FROM USER_LOGIN_HISTORY WHERE auth_type IN ('PASSWORD', 'SOCIAL') GROUP BY user_idx ) h ON u.user_idx = h.user_idx
AND u.account_status = #{status}
AND u.user_role = #{role}
AND s.user_idx IS NULL
AND FIND_IN_SET(#{provider}, IFNULL(s.linked_providers, '')) > 0
AND DATE(u.created_at) >= #{dateFrom}
AND DATE(u.created_at) <= #{dateTo}
AND u.user_id LIKE CONCAT('%', #{keyword}, '%')
AND u.nickname LIKE CONCAT('%', #{keyword}, '%')
AND u.user_email LIKE CONCAT('%', #{keyword}, '%')
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT COUNT(*) > 0
FROM ADMIN_EFFECTIVE_PERMISSION_VW
WHERE user_idx = #{userIdx}
  AND permission_code = #{permissionCode}

SELECT *
FROM USER_LOGIN_HISTORY
WHERE user_idx = #{userIdx}
ORDER BY login_at DESC
LIMIT #{limit}

mapper.update:
UPDATE INQUIRY_ANSWER
SET content = #{content}, updated_at = NOW()
WHERE answer_id = #{answerId}

UPDATE INQUIRY_POST
SET status = #{status}, updated_at = NOW()
WHERE inquiry_id = #{inquiryId}

mapper.sql:
FROM USER_LOGIN_HISTORY h LEFT JOIN USERS u ON h.user_idx = u.user_idx
AND h.is_success = TRUE
AND h.is_success = FALSE
AND h.auth_type = #{authType}
AND h.login_method = #{loginMethod}
AND ( h.login_identifier LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') )

FROM USER_SECURITY_HISTORY s LEFT JOIN USERS u ON s.user_idx = u.user_idx LEFT JOIN USERS au ON s.actor_user_idx = au.user_idx
AND s.is_success = TRUE
AND s.is_success = FALSE
AND s.event_type = #{eventType}
AND s.event_stage = #{eventStage}
AND ( IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(au.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(au.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.input_identifier, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.target_email, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') )

FROM EMAIL_VERIFICATION_REQUEST r LEFT JOIN USERS u ON r.user_idx = u.user_idx
AND r.status = #{status}
AND r.purpose = #{purpose}
AND ( IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(r.pending_email, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(r.request_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(r.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') )

FROM USER_ACTIVITY_LOG a LEFT JOIN USERS u ON a.user_idx = u.user_idx
AND a.is_success = TRUE
AND a.is_success = FALSE
AND a.activity_type = #{activityType}
AND a.http_method = #{httpMethod}
AND ( IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(a.request_uri, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(a.activity_code, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(a.target_type, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(a.target_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(a.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') )

FROM REPORT r
LEFT JOIN USERS u ON r.user_idx = u.user_idx


        AND r.status = #{status}


        AND r.target_type = #{targetType}


        AND r.reason = #{reason}


        AND u.nickname LIKE CONCAT('%', #{keyword}, '%')
